-- Seeds the two pre-existing blog posts into the new posts table.
-- Applied via `npx supabase db push`.

insert into posts (slug, title, excerpt, category, body_json, visibility, published_at)
values (
  'why-luxury-real-estate-content-needs-a-different-strategy',
  'Why Luxury Real Estate Content Needs a Completely Different Strategy',
  'Luxury real estate is not sold — it is desired. The content strategy for an AED 10M property is fundamentally different from any other category, and most agencies get it wrong.',
  'Strategy',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Most real estate content makes the same mistake: it leads with features. 4 bedrooms. 3 bathrooms. 2,400 sq ft. Private pool. Sea view. This is spec-sheet marketing, and it doesn''t sell luxury property."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Luxury is an Emotion, Not a Feature List"}]},{"type":"paragraph","content":[{"type":"text","text":"The buyer of an AED 10M+ property in Dubai is not making a spreadsheet decision. They are making an identity decision. The content has to answer one question: "},{"type":"text","text":"Is this property consistent with who I am?","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"That means the photography, the copy, the music in the reel, the pacing of the edit — all of it has to communicate status, taste, and aspiration before it communicates square footage."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The Channel Mix is Different"}]},{"type":"paragraph","content":[{"type":"text","text":"Instagram Reels work for clinic content. They do not work for AED 15M villas. The luxury real estate buyer is on LinkedIn, on private WhatsApp groups, on YouTube watching 4K cinematic walkthroughs. The distribution strategy has to match where the buyer actually lives online."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Content Formats That Actually Convert"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Cinematic 60-90 second property films (not slideshows)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Neighbourhood lifestyle content — sell the life, not the flat"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Developer credibility content — who built this, what else have they built"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ROI and investment angle content for investor buyers"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The Macins Luxe Approach"}]},{"type":"paragraph","content":[{"type":"text","text":"For Macins Luxe Properties, we built a content system around lifestyle aspiration first, property second. Every piece of content was designed to make the viewer feel something before they knew the price. That emotional connection is what turns a viewer into an enquiry."}]}]}'::jsonb,
  'public',
  now()
)
on conflict (slug) do update set
  title = excluded.title,
  excerpt = excluded.excerpt,
  category = excluded.category,
  body_json = excluded.body_json;

insert into posts (slug, title, excerpt, category, body_json, visibility, published_at)
values (
  'my-ai-workflow-for-managing-multiple-brands',
  'My AI Workflow for Managing Multiple Brands',
  'How I use Claude AI, ChatGPT, Midjourney, CapCut AI, and Make.com to deliver high-output marketing across five business units at once — without burning out.',
  'AI & Productivity',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Five business units. Different industries. Different brand voices. 30+ pieces of content each, every month. Consistent output at that volume isn''t sustainable without systems — and those systems are now largely AI-powered."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The Stack"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Claude AI","marks":[{"type":"bold"}]},{"type":"text","text":" — Strategy documents, long-form copy, campaign briefs, brand voice calibration."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ChatGPT","marks":[{"type":"bold"}]},{"type":"text","text":" — Rapid caption variations, hashtag research, quick ideation sessions."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Midjourney","marks":[{"type":"bold"}]},{"type":"text","text":" — Concept visuals, moodboards, creative direction references."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Canva AI","marks":[{"type":"bold"}]},{"type":"text","text":" — Template production at scale, brand kit application, Magic Resize for cross-platform adaptation."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"CapCut AI","marks":[{"type":"bold"}]},{"type":"text","text":" — Reel editing, auto-captions, template-based video production."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Make.com","marks":[{"type":"bold"}]},{"type":"text","text":" — Automation flows: content approval → scheduling → reporting pipelines."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Notion AI","marks":[{"type":"bold"}]},{"type":"text","text":" — Content calendar management, brand briefing documents, campaign trackers."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The Weekly Rhythm"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Monday","marks":[{"type":"bold"}]},{"type":"text","text":" — Strategy and planning. Claude AI generates weekly content briefs based on brand guidelines and current campaign objectives."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tuesday–Wednesday","marks":[{"type":"bold"}]},{"type":"text","text":" — Content production, in batches. Canva templates, Midjourney visuals, AI-assisted copy."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Thursday","marks":[{"type":"bold"}]},{"type":"text","text":" — Stakeholder review and approval, with Make.com handling the feedback loop."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Friday","marks":[{"type":"bold"}]},{"type":"text","text":" — Scheduling and the following week''s brief prep."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The Non-Negotiable"}]},{"type":"paragraph","content":[{"type":"text","text":"AI handles speed. Strategy is still human. Every piece of content is reviewed for brand alignment, strategic intent, and quality before it goes out. The AI compresses the production timeline — it doesn''t replace judgement."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The Result"}]},{"type":"paragraph","content":[{"type":"text","text":"The AI stack has cut the time this used to take dramatically. Not at reduced quality — at higher quality, because more time goes into strategy and less into admin."}]}]}'::jsonb,
  'public',
  now()
)
on conflict (slug) do update set
  title = excluded.title,
  excerpt = excluded.excerpt,
  category = excluded.category,
  body_json = excluded.body_json;

